package api_test

import (
	"net/http"
	"strings"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

// These tests act as Acme and reach for Globex's objects. Every answer must be the one for an ID that does not exist, and
// Globex's data must not change.

const unknownID = "nope_000000"

// globexObjects are one of each kind of object that Globex owns, by ID.
type globexObjects struct {
	customer, plan, subscription, invoice, endpoint, event, invite, apiKey, member string
}

func makeGlobexObjects(t *testing.T, e *apitest.Env) globexObjects {
	t.Helper()
	c := e.CreateCustomer(e.Globex, "Gil", "gil@globex.example")
	p := e.CreatePlan(e.Globex, "Business", "EUR", "10.00")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Globex.Key, map[string]any{"customer_id": c.ID, "plan_id": p.ID, "quantity": 1}, &sub)
	var inv store.Invoice
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Globex.Key, map[string]any{"customer_id": c.ID, "currency": "EUR",
		"lines": []map[string]any{{"description": "Seats", "quantity": 1, "unit_amount": 1000}}}, &inv)
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Globex.Key, map[string]any{"url": "https://hooks.globex.example/tally", "events": []string{"customer.created"}}, &ep)
	var evs struct {
		Items []store.Event `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/events", e.Globex.Key, nil, &evs)
	if len(evs.Items) == 0 {
		t.Fatal("Globex has no events")
	}
	var invite store.Invite
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Globex.Key, map[string]any{"email": "new@globex.example", "role": "member"}, &invite)
	key, ok := e.Store.APIKeyByToken(e.Globex.Key)
	if !ok {
		t.Fatal("Globex's key is unknown")
	}
	return globexObjects{customer: c.ID, plan: p.ID, subscription: sub.ID, invoice: inv.ID, endpoint: ep.ID,
		event: evs.Items[0].ID, invite: invite.ID, apiKey: key.ID, member: e.Globex.Owner.ID}
}

// probe is one request that names an object of another organization: in the path ({id}) or in the body.
type probe struct {
	name   string
	method string
	path   string
	body   func(id string) any
	id     string // Globex's object
}

func TestAnotherOrgsObjectsLookLikeUnknownOnes(t *testing.T) {
	e := apitest.New(t)
	g := makeGlobexObjects(t, e)
	acmeCustomer := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	acmePlan := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	none := func(string) any { return nil }
	json := func(v map[string]any) func(string) any { return func(string) any { return v } }

	probes := []probe{
		{"get customer", "GET", "/v1/customers/{id}", none, g.customer},
		{"update customer", "PATCH", "/v1/customers/{id}", json(map[string]any{"name": "Hacked"}), g.customer},
		{"delete customer", "DELETE", "/v1/customers/{id}", none, g.customer},
		{"get plan", "GET", "/v1/plans/{id}", none, g.plan},
		{"update plan", "PATCH", "/v1/plans/{id}", json(map[string]any{"name": "Hacked"}), g.plan},
		{"get subscription", "GET", "/v1/subscriptions/{id}", none, g.subscription},
		{"update subscription", "PATCH", "/v1/subscriptions/{id}", json(map[string]any{"quantity": 5}), g.subscription},
		{"cancel subscription", "POST", "/v1/subscriptions/{id}/cancel", none, g.subscription},
		{"report usage", "POST", "/v1/subscriptions/{id}/usage", json(map[string]any{"quantity": 1}), g.subscription},
		{"get invoice", "GET", "/v1/invoices/{id}", none, g.invoice},
		{"get invoice lines", "GET", "/v1/invoices/{id}/lines", none, g.invoice},
		{"pay invoice", "POST", "/v1/invoices/{id}/pay", none, g.invoice},
		{"void invoice", "POST", "/v1/invoices/{id}/void", none, g.invoice},
		{"get webhook endpoint", "GET", "/v1/webhook-endpoints/{id}", none, g.endpoint},
		{"update webhook endpoint", "PATCH", "/v1/webhook-endpoints/{id}", json(map[string]any{"enabled": false}), g.endpoint},
		{"delete webhook endpoint", "DELETE", "/v1/webhook-endpoints/{id}", none, g.endpoint},
		{"list webhook deliveries", "GET", "/v1/webhook-endpoints/{id}/deliveries", none, g.endpoint},
		{"get event", "GET", "/v1/events/{id}", none, g.event},
		{"revoke invite", "DELETE", "/v1/invites/{id}", none, g.invite},
		{"revoke api key", "DELETE", "/v1/api-keys/{id}", none, g.apiKey},
		{"update member", "PATCH", "/v1/members/{id}", json(map[string]any{"role": "viewer"}), g.member},
		{"remove member", "DELETE", "/v1/members/{id}", none, g.member},
		// IDs named in the body.
		{"subscribe another org's customer", "POST", "/v1/subscriptions",
			func(id string) any { return map[string]any{"customer_id": id, "plan_id": acmePlan.ID, "quantity": 1} }, g.customer},
		{"subscribe to another org's plan", "POST", "/v1/subscriptions",
			func(id string) any { return map[string]any{"customer_id": acmeCustomer.ID, "plan_id": id, "quantity": 1} }, g.plan},
		{"invoice another org's customer", "POST", "/v1/invoices",
			func(id string) any {
				return map[string]any{"customer_id": id, "currency": "USD", "lines": []map[string]any{{"description": "x", "quantity": 1, "unit_amount": 100}}}
			}, g.customer},
	}
	for _, p := range probes {
		t.Run(p.name, func(t *testing.T) {
			want := e.Do(p.method, strings.ReplaceAll(p.path, "{id}", unknownID), e.Acme.Key, p.body(unknownID))
			if want.Code != http.StatusNotFound || want.Map(t)["error"] != "not_found" {
				t.Fatalf("an unknown ID answers %s", want)
			}
			got := e.Do(p.method, strings.ReplaceAll(p.path, "{id}", p.id), e.Acme.Key, p.body(p.id))
			if got.Code != want.Code || string(got.Body) != string(want.Body) {
				t.Fatalf("another organization's ID answers %s, an unknown one %s", got, want)
			}
		})
	}

	// None of it changed Globex's data, or created anything for Acme.
	var c store.Customer
	e.MustDo(http.StatusOK, "GET", "/v1/customers/"+g.customer, e.Globex.Key, nil, &c)
	if c.Name != "Gil" {
		t.Fatalf("Globex's customer changed: %+v", c)
	}
	var inv store.Invoice
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+g.invoice, e.Globex.Key, nil, &inv)
	if inv.Status != store.InvoiceOpen || len(inv.Lines) != 1 {
		t.Fatalf("Globex's invoice changed: %+v", inv)
	}
	var sub store.Subscription
	e.MustDo(http.StatusOK, "GET", "/v1/subscriptions/"+g.subscription, e.Globex.Key, nil, &sub)
	if sub.Quantity != 1 {
		t.Fatalf("Globex's subscription changed: %+v", sub)
	}
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusOK, "GET", "/v1/webhook-endpoints/"+g.endpoint, e.Globex.Key, nil, &ep)
	if !ep.Enabled {
		t.Fatalf("Globex's endpoint changed: %+v", ep)
	}
	var invites struct {
		Items []store.Invite `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invites", e.Globex.Key, nil, &invites)
	if len(invites.Items) != 1 {
		t.Fatalf("Globex's invites changed: %+v", invites.Items)
	}
	var members struct {
		Items []struct {
			UserID string     `json:"user_id"`
			Role   store.Role `json:"role"`
		} `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/members", e.Globex.Key, nil, &members)
	if len(members.Items) != 1 || members.Items[0].Role != store.RoleOwner {
		t.Fatalf("Globex's members changed: %+v", members.Items)
	}
	if r := e.Do("GET", "/v1/me", e.Globex.Key, nil); r.Code != http.StatusOK {
		t.Fatalf("Globex's key was revoked: %s", r)
	}
	for _, path := range []string{"/v1/customers", "/v1/subscriptions", "/v1/invoices"} {
		var out struct {
			Items []any `json:"items"`
		}
		e.MustDo(http.StatusOK, "GET", path, e.Acme.Key, nil, &out)
		if len(out.Items) != 1 && path == "/v1/customers" || len(out.Items) != 0 && path != "/v1/customers" {
			t.Fatalf("Acme's %s after the probes: %d items", path, len(out.Items))
		}
	}
}

// Lists filtered by an ID of another organization are empty, as they are for an unknown ID.
func TestListFiltersDoNotShowAnotherOrgsObjects(t *testing.T) {
	e := apitest.New(t)
	g := makeGlobexObjects(t, e)
	for _, path := range []string{
		"/v1/invoices?customer_id=" + g.customer,
		"/v1/invoices?subscription_id=" + g.subscription,
		"/v1/subscriptions?customer_id=" + g.customer,
		"/v1/payments?invoice_id=" + g.invoice,
	} {
		var out struct {
			Items []any `json:"items"`
		}
		e.MustDo(http.StatusOK, "GET", path, e.Acme.Key, nil, &out)
		if len(out.Items) != 0 {
			t.Fatalf("%s shows %d of another organization's items", path, len(out.Items))
		}
	}
}

// An email address is unique within an organization only: two organizations can each have a customer with the same one, and
// neither affects the other's lookups, updates or deletes.
func TestEmailLookupsAreOrgScoped(t *testing.T) {
	e := apitest.New(t)
	// Globex's customer is created second in each pair, the order that overwrote the other organization's entry.
	aJane := e.CreateCustomer(e.Acme, "Jane Acme", "jane@example.com")
	gJane := e.CreateCustomer(e.Globex, "Jane Globex", "Jane@Example.com")
	gBob := e.CreateCustomer(e.Globex, "Bob Globex", "bob@example.com")
	aBob := e.CreateCustomer(e.Acme, "Bob Acme", "bob@example.com")
	gOnly := e.CreateCustomer(e.Globex, "Only Globex", "only@globex.example")

	lookup := func(org apitest.Org, email string) []store.Customer {
		t.Helper()
		var out struct {
			Items []store.Customer `json:"items"`
		}
		e.MustDo(http.StatusOK, "GET", "/v1/customers?email="+email, org.Key, nil, &out)
		return out.Items
	}
	expect := func(org apitest.Org, email string, want ...store.Customer) {
		t.Helper()
		got := lookup(org, email)
		if len(got) != len(want) || (len(want) == 1 && got[0].ID != want[0].ID) {
			t.Fatalf("lookup %s by %s = %+v, want %+v", org.Name, email, got, want)
		}
	}
	expect(e.Acme, "jane@example.com", aJane)
	expect(e.Globex, "jane@example.com", gJane)
	expect(e.Acme, "bob@example.com", aBob)
	expect(e.Globex, "bob@example.com", gBob)
	expect(e.Acme, "only@globex.example")

	// Globex changes and removes its address; Acme's lookups are unaffected.
	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+gJane.ID, e.Globex.Key, map[string]any{"email": "jane.globex@example.com"}, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+gBob.ID, e.Globex.Key, nil, nil)
	expect(e.Acme, "jane@example.com", aJane)
	expect(e.Acme, "bob@example.com", aBob)
	expect(e.Globex, "jane.globex@example.com", gJane)
	expect(e.Globex, "only@globex.example", gOnly)

	// Globex can reuse the address Acme holds, and Acme's customer stays the one Acme finds.
	gAgain := e.CreateCustomer(e.Globex, "Jane Again", "jane@example.com")
	expect(e.Acme, "jane@example.com", aJane)
	expect(e.Globex, "jane@example.com", gAgain)
}

