package store

import (
	"errors"
	"testing"
)

func TestCustomerEmailsArePerOrganization(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "A"), newOrg(t, s, "B")
	ca, err := s.CreateCustomer(a.ID, "Ann", "ann@example.com", t0)
	if err != nil {
		t.Fatal(err)
	}
	cb, err := s.CreateCustomer(b.ID, "Bea", "ANN@example.com", t0)
	if err != nil {
		t.Fatalf("the same address in another org: %v", err)
	}
	if got, ok := s.FindCustomerByEmail(a.ID, "ann@example.com"); !ok || got.ID != ca.ID {
		t.Fatalf("A's lookup = %+v %v, want %s", got, ok, ca.ID)
	}
	if got, ok := s.FindCustomerByEmail(b.ID, "ann@example.com"); !ok || got.ID != cb.ID {
		t.Fatalf("B's lookup = %+v %v, want %s", got, ok, cb.ID)
	}
	if _, err := s.UpdateCustomer(b.ID, cb.ID, func(c *Customer) error { c.Email = "bea@example.com"; return nil }); err != nil {
		t.Fatal(err)
	}
	if err := s.DeleteCustomer(b.ID, cb.ID); err != nil {
		t.Fatal(err)
	}
	if got, ok := s.FindCustomerByEmail(a.ID, "ann@example.com"); !ok || got.ID != ca.ID {
		t.Fatalf("A's lookup after B changed its customer = %+v %v", got, ok)
	}
	if _, ok := s.FindCustomerByEmail(b.ID, "ann@example.com"); ok {
		t.Fatal("B finds A's customer by email")
	}
}

func TestWebhookEndpointDeleteIsOrgScoped(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "A"), newOrg(t, s, "B")
	ep, err := s.CreateWebhookEndpoint(WebhookEndpoint{OrgID: b.ID, URL: "https://b.example/hook", Events: []string{"*"}, Enabled: true}, t0)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.DeleteOrgWebhookEndpoint(a.ID, ep.ID); !errors.Is(err, ErrNotFound) {
		t.Fatalf("A deleted B's endpoint: %v", err)
	}
	if _, ok := s.WebhookEndpoint(b.ID, ep.ID); !ok {
		t.Fatal("B's endpoint is gone after A's delete")
	}
	if err := s.DeleteOrgWebhookEndpoint(b.ID, ep.ID); err != nil {
		t.Fatalf("B deletes its own endpoint: %v", err)
	}
}

