129	// getInvoiceLines answers an invoice's lines with each line's amount, for the dashboard's invoice table.
130	func (s *Server) getInvoiceLines(w http.ResponseWriter, r *http.Request, p auth.Principal) {
131		inv, ok := s.store.Invoice(p.OrgID, r.PathValue("id"))
132		if !ok {
133			writeError(w, http.StatusNotFound, "not_found", "no such invoice")
134			return
135		}
136		type lineView struct {
137			store.Line
138			Amount int64 `json:"amount"`
139		}
140		items := []lineView{}
141		for _, l := range inv.Lines {
142			items = append(items, lineView{Line: l, Amount: l.Amount()})
143		}
144		writeJSON(w, http.StatusOK, list{Items: items})
145	}
