147	// payInvoice charges an invoice: {"payment_method": "pm_..."}, or the customer's default payment method when it is absent.
148	func (s *Server) payInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
149		var in struct {
150			PaymentMethod string `json:"payment_method"`
151		}
152		if r.ContentLength != 0 && !decode(w, r, &in) {
153			return
154		}
155		inv, pay, err := s.pay.Pay(r.Context(), p.OrgID, r.PathValue("id"), in.PaymentMethod)
156		if err != nil {
157			s.payError(w, err)
158			return
159		}
160		writeJSON(w, http.StatusOK, map[string]any{"invoice": s.viewInvoice(inv), "payment": pay})
161	}
162	
163	func (s *Server) payError(w http.ResponseWriter, err error) {
164		var decline *payments.DeclineError
165		switch {
166		case errors.As(err, &decline):
167			writeJSON(w, http.StatusPaymentRequired, map[string]string{"error": "payment_declined", "decline_code": decline.Code, "message": err.Error()})
168		case errors.Is(err, payments.ErrAlreadyPaid):
169			writeError(w, http.StatusConflict, "already_paid", err.Error())
170		case errors.Is(err, payments.ErrInvoiceVoid):
171			writeError(w, http.StatusConflict, "invoice_void", err.Error())
172		case errors.Is(err, payments.ErrNoPaymentMethod):
173			writeError(w, http.StatusUnprocessableEntity, "no_payment_method", err.Error())
174		case errors.Is(err, payments.ErrUnavailable):
175			writeError(w, http.StatusServiceUnavailable, "gateway_unavailable", "the payment gateway is unavailable; nothing was charged, try again")
176		default:
177			s.storeError(w, err)
178		}
179	}
180	
181	func (s *Server) voidInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
182		now := s.clock.Now()
183		inv, err := s.store.UpdateInvoice(p.OrgID, r.PathValue("id"), func(inv *store.Invoice) error {
184			switch inv.Status {
185			case store.InvoicePaid:
186				return payments.ErrAlreadyPaid
187			case store.InvoiceVoid:
188				return payments.ErrInvoiceVoid
189			}
190			inv.Status, inv.VoidedAt = store.InvoiceVoid, &now
191			return nil
192		})
193		if err != nil {
194			s.payError(w, err)
195			return
196		}
197		s.publish(r.Context(), p.OrgID, "invoice.voided", map[string]any{"invoice_id": inv.ID})
198		writeJSON(w, http.StatusOK, s.viewInvoice(inv))
199	}
