331	// UpdateInvoice changes an invoice with f, which may refuse with an error. Only its status, timestamps and lines change.
332	func (s *Store) UpdateInvoice(orgID, id string, f func(*Invoice) error) (Invoice, error) {
333		s.mu.Lock()
334		defer s.mu.Unlock()
335		old, ok := s.invoices[id]
336		if !ok || old.OrgID != orgID {
337			return Invoice{}, ErrNotFound
338		}
339		inv := copyInvoice(old)
340		if err := f(&inv); err != nil {
341			return Invoice{}, err
342		}
343		inv.ID, inv.OrgID, inv.CustomerID, inv.SubscriptionID, inv.Currency, inv.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.SubscriptionID, old.Currency, old.CreatedAt
344		s.invoices[id] = copyInvoice(inv)
345		return copyInvoice(inv), nil
346	}
347	
348	// copyInvoice is a deep copy, so callers cannot change stored lines.
349	func copyInvoice(inv Invoice) Invoice {
350		inv.Lines = append([]Line(nil), inv.Lines...)
351		for _, p := range []**time.Time{&inv.PeriodStart, &inv.PeriodEnd, &inv.PaidAt, &inv.VoidedAt} {
352			if *p != nil {
353				t := **p
354				*p = &t
355			}
356		}
357		return inv
358	}
359	
360	// cloneInvoice is a deep copy through JSON, which cannot miss a field added later.
361	func cloneInvoice(inv Invoice) Invoice {
362		b, err := json.Marshal(inv)
363		if err != nil {
364			return copyInvoice(inv)
365		}
366		var out Invoice
367		if err := json.Unmarshal(b, &out); err != nil {
368			return copyInvoice(inv)
369		}
370		return out
371	}
