303	// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
304	func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
305		s.mu.Lock()
306		all := make([]Invoice, 0, len(s.invoices))
307		for _, inv := range s.invoices {
308			all = append(all, inv)
309		}
310		s.mu.Unlock()
311		out := []Invoice{}
312		for _, inv := range all {
313			c := cloneInvoice(inv)
314			if c.OrgID != orgID {
315				continue
316			}
317			if (f.CustomerID != "" && c.CustomerID != f.CustomerID) || (f.SubscriptionID != "" && c.SubscriptionID != f.SubscriptionID) || (f.Status != "" && c.Status != f.Status) {
318				continue
319			}
320			out = append(out, c)
321		}
322		sort.Slice(out, func(i, j int) bool {
323			if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
324				return out[i].CreatedAt.Before(out[j].CreatedAt)
325			}
326			return out[i].ID < out[j].ID
327		})
328		return out
329	}
