392	// Payments returns an organization's payments, oldest first, only those of one invoice when invoiceID is set.
393	func (s *Store) Payments(orgID, invoiceID string) []Payment {
394		s.mu.Lock()
395		defer s.mu.Unlock()
396		out := []Payment{}
397		for _, p := range s.payments {
398			if p.OrgID == orgID && (invoiceID == "" || p.InvoiceID == invoiceID) {
399				out = append(out, p)
400			}
401		}
402		sort.Slice(out, func(i, j int) bool {
403			if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
404				return out[i].CreatedAt.Before(out[j].CreatedAt)
405			}
406			return out[i].ID < out[j].ID
407		})
408		return out
409	}
